"use strict";(self.webpackChunkmantis_docs=self.webpackChunkmantis_docs||[]).push([[885],{3794:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>a,default:()=>h,frontMatter:()=>o,metadata:()=>r,toc:()=>c});var i=n(4848),s=n(8453);const o={sidebar_position:7},a="Roadmap",r={id:"protocol/roadmap",title:"Roadmap",description:"Additional features that we plan to add to Mantis include the following:",source:"@site/docs/protocol/roadmap.md",sourceDirName:"protocol",slug:"/protocol/roadmap",permalink:"/protocol/roadmap",draft:!1,unlisted:!1,editUrl:"https://github.com/ComposableFi/mantis-docs/docs/protocol/roadmap.md",tags:[],version:"current",sidebarPosition:7,frontMatter:{sidebar_position:7},sidebar:"protocol",previous:{title:"Audits",permalink:"/protocol/audits"}},l={},c=[{value:"Conditional Intents",id:"conditional-intents",level:3},{value:"The Path to Decentralization",id:"the-path-to-decentralization",level:3},{value:"Security from the L1",id:"security-from-the-l1",level:3},{value:"Cross-Domain Expressiveness and Atomicity",id:"cross-domain-expressiveness-and-atomicity",level:2},{value:"Decentralized Sequencing",id:"decentralized-sequencing",level:3}];function d(e){const t={a:"a",h1:"h1",h2:"h2",h3:"h3",header:"header",li:"li",ol:"ol",p:"p",strong:"strong",ul:"ul",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"roadmap",children:"Roadmap"})}),"\n",(0,i.jsx)(t.p,{children:"Additional features that we plan to add to Mantis include the following:"}),"\n",(0,i.jsx)(t.h3,{id:"conditional-intents",children:"Conditional Intents"}),"\n",(0,i.jsx)(t.p,{children:"While intents in decentralized finance (DeFi) are often described as a broad concept, current intent-based applications typically focus on a limited set of intent types. These commonly take the form of limit orders or bridge transactions, such as:"}),"\n",(0,i.jsxs)(t.ol,{children:["\n",(0,i.jsx)(t.li,{children:'"Trade asset A for asset B with a minimum price p"'}),"\n",(0,i.jsx)(t.li,{children:'"Transfer asset A to domain Z"'}),"\n"]}),"\n",(0,i.jsx)(t.p,{children:'However, the theoretical potential of intents extends far beyond these basic use cases. Ideally, intents should serve as a tool allowing agents to express "arbitrary" preferences over state transitions within a single domain or across multiple domains.'}),"\n",(0,i.jsx)(t.p,{children:"In economic literature, limit price-type intents can be conceptualized as expressions of an agent's private valuations over assets. Private valuations refer to the subjective worth an individual assigns to an asset, independent of others' opinions or market conditions. For instance, an individual might value a rare coin based on personal interest or sentimental attachment, regardless of its market price (also known as Walrasian demands)."}),"\n",(0,i.jsx)(t.p,{children:"However, it's crucial to recognize that users and agents often do not operate solely on private valuations. In reality, economic actors are interdependent, and their valuations of certain objects can depend significantly on the valuations of others. A prime example of this phenomenon is the valuation of digital art."}),"\n",(0,i.jsx)(t.p,{children:"In such cases, if no one expresses any valuation for an item, people generally wouldn't value it. Conversely, when an item experiences high demand, agents often interpret this demand as a positive signal, indicating that the item possesses some intrinsic value. This concept aligns with the greater fool theory and speculative bubbles in financial markets."}),"\n",(0,i.jsx)(t.p,{children:"Given this reality, intents should be capable of capturing these interdependent valuations. Many items are not valued in isolation from the world (unlike, for example, consuming an apple, which is generally independent of others' consumption). Instead, their value is deeply intertwined with other agents' valuations."}),"\n",(0,i.jsx)(t.p,{children:"Natural examples of interdependent valuations that could be expressed through more sophisticated intents include:"}),"\n",(0,i.jsxs)(t.ol,{children:["\n",(0,i.jsx)(t.li,{children:"Stop-losses: An order to sell an asset when it reaches a certain price, reflecting a valuation dependent on market movements."}),"\n",(0,i.jsx)(t.li,{children:"Bidding in NFT auctions: Where the perceived value of an NFT can be influenced by the bids of other participants."}),"\n",(0,i.jsx)(t.li,{children:"Copy-trading strategies: Where an agent's trading decisions are based on the actions of another trader (use other traders actions as positive or negative signals)."}),"\n",(0,i.jsx)(t.li,{children:"Dynamic liquidity provision: Adjusting liquidity based on market volatility or trading volume."}),"\n",(0,i.jsx)(t.li,{children:"Trading conditional to prediction market quotes on real events."}),"\n"]}),"\n",(0,i.jsxs)(t.p,{children:["By expanding the concept of intents to encompass these interdependent valuations, DeFi protocols and users can more accurately reflect the complex decision-making processes of market participants. This evolution could lead to more efficient markets, improved price discovery mechanisms, and a closer alignment between DeFi systems and real-world economic behaviors. We call this subset of intents ",(0,i.jsx)(t.strong,{children:"conditional intents"}),", emphasizing that the execution of such is conditioned to external signals or events."]}),"\n",(0,i.jsx)(t.p,{children:"Because intents on Mantis are generalized, artificial intelligence (AI) agents will be capable of submitting time-based conditional intents through the protocol. For example, a user may want to make a particular swap at the best price within the next 48 hours. They provide this information to the AI agent, which makes a prediction about when the best price will be within this time constraint. Then, at this time, the AI agent submits an intent to carry out the swap to Mantis. This abstracts conditionality away from solvers and puts it in the hands of AI agents who likely have more powerful algorithms to determine the best timing of swaps. Then, solvers are left to handle identification and execution of the best transaction route at that time. In this manner, the strengths and optimizations of the Mantis protocol and of AI agents are able to synergize, providing the best execution."}),"\n",(0,i.jsx)(t.h3,{id:"the-path-to-decentralization",children:"The Path to Decentralization"}),"\n",(0,i.jsx)(t.p,{children:"It is important for Mantis to become as decentralized as possible; decentralized structures are more secure, transparent, and resilient to attacks or failures compared to centralized structures. However, a completely decentralized ecosystem is incredibly developmentally intensive. In the interest of being able to provide users with the Mantis solution in an expedient manner, we are rolling out some features that are more centralized at first."}),"\n",(0,i.jsx)(t.p,{children:"The Rollup is the cornerstone for making this architecture truly decentralized. Currently, the Auctioneer holds some central power, which could lead to potential misbehavior. The goal is to migrate the off-chain Auctioneer to the Rollup, ensuring a fairer system for both Users and Solvers. Over time, we will continue to make these components more decentralized according to the outline below:"}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.strong,{children:"On-Chain Auctioneer Functionality:"})}),"\n",(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsx)(t.li,{children:"The Escrow contract on the Rollup will incorporate the Auctioneer's role, bringing the auction process on-chain. Users will send their intents directly to the Rollup."}),"\n",(0,i.jsx)(t.li,{children:"Solvers will monitor these intents and decide if they want to participate in the auction. The auction itself will occur on-chain within the Escrow contract."}),"\n"]}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.strong,{children:"Transparency and Monitoring:"})}),"\n",(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsxs)(t.li,{children:["The future vision includes a Front-End blockchain explorer that pulls data from the Escrow Contract on the Rollup. This explorer will display critical information, such as:","\n",(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Pending Intents:"})," Whether they are private or public for discussion."]}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"On-Execution Intents:"})," Intents currently being processed."]}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Executed Intents:"})," Intents that have been fully executed."]}),"\n"]}),"\n"]}),"\n",(0,i.jsx)(t.li,{children:"Essentially, the Escrow contract on the Rollup will act as a mempool for intents, providing transparency and allowing all participants to monitor the process."}),"\n"]}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.strong,{children:"Slashing Parameters:"})}),"\n",(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsx)(t.li,{children:"We will implement slashing parameters for solvers, relayers/sequencers, and block producers to disincentivize misbehavior."}),"\n"]}),"\n",(0,i.jsx)(t.h3,{id:"security-from-the-l1",children:"Security from the L1"}),"\n",(0,i.jsx)(t.p,{children:"In the Ethereum context, there are two requirements for being a rollup:"}),"\n",(0,i.jsxs)(t.ol,{children:["\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Rollback based on the L1:"})," Rollup blocks are validated by the corresponding L1. If the L1 says the transaction is invalid (i.e. the L1 does not accept the transaction), the rollup rolls it back."]}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Emergency withdrawals from L1 using the L2:"})," The state root can be used to make an emergency withdrawal from the layer 2 in the event the L2 stops running."]}),"\n"]}),"\n",(0,i.jsx)(t.p,{children:"The Mantis rollup is being developed to fit these requirements."}),"\n",(0,i.jsx)(t.h2,{id:"cross-domain-expressiveness-and-atomicity",children:"Cross-Domain Expressiveness and Atomicity"}),"\n",(0,i.jsx)(t.p,{children:"Pricing cross-domain intent solutions presents multiple challenges for solvers. These challenges are primarily financial. Solvers must first manage the initial expenses related to setting up infrastructure necessary for participating in intent markets. Additionally, congestion costs arise when entering the market; these costs vary depending on the number of competitors and affect solvers while they vie for opportunities. Finally, solvers contend with the risk of non-atomic execution due to the lack of expressiveness of blockspace allocation for multiple chains. This further complicates their operational landscape."}),"\n",(0,i.jsx)(t.p,{children:"Thus arises a need for mechanisms that mitigate these costs for solvers and potentially enhance overall user welfare. Moreover, such mechanisms will reduce the cost of MEV extraction between chains and increase the revenue of validators, as has been seen in single-domain MEV auctions."}),"\n",(0,i.jsx)(t.p,{children:"Our thesis is that users, searchers, and solvers have preferences over different domains. Further, these parties can accrue value from combinatorial state transitions over different domains. An example is a searcher that exploits price discrepancies of DEXes on two different domains. However, these preferences over state transition currently lack the necessary infrastructure to be expressed atomically. At most, currently users bid simultaneously on an independent auction in the hopes of getting all transactions executed. However, there is a high risk of execution failure."}),"\n",(0,i.jsx)(t.p,{children:"To mitigate this, Mantis will coordinate various actors to sell blocks from different domains through a combinatorial auction. Mantis combinatorial auctions will enable builders and searchers to express bundles through different domains. This will facilitate the following benefits:"}),"\n",(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsx)(t.li,{children:"Atomicity"}),"\n",(0,i.jsx)(t.li,{children:"More revenue to validators that sell their items separately"}),"\n",(0,i.jsx)(t.li,{children:"Efficient blockspace allocation"}),"\n"]}),"\n",(0,i.jsx)(t.p,{children:"The initial design is just-in-time auctions to allow builders to express atomically. This design for two domains will consist of two simultaneous English auctions with a unique combinatorial block take-it-or-leave it offer. Buyers will be able to place send blocks with bids for the independent blocks and combinatorial blocks."}),"\n",(0,i.jsx)(t.p,{children:"This approach poses two main challenges: the risk of double-signing and the high level of trust placed in the relay. Thus, in the future, Mantis aims to introduce a future blockspace market, where the rights to future blockspace on multiple domains can be bought and sold. This aims to decrease the monopolistic power of sellers selling combinations of blocks while increasing market efficiency."}),"\n",(0,i.jsxs)(t.p,{children:["Both the initial just-in-time auctions and the more advanced combinatorial blockspace future markets are described in detail in the ",(0,i.jsx)(t.a,{href:"https://assets.website-files.com/65b28e756a8eda2e91e76ca4/6656289f21123d6215091555_MANTIS%20Whitepaper.pdf",children:"Mantis Whitepaper"}),"."]}),"\n",(0,i.jsx)(t.h3,{id:"decentralized-sequencing",children:"Decentralized Sequencing"}),"\n",(0,i.jsx)(t.p,{children:"Sequencers are network nodes that play critical roles on a rollup. These roles include:"}),"\n",(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsx)(t.li,{children:"Aggregating, ordering, and executing transactions"}),"\n",(0,i.jsx)(t.li,{children:"Producing preconfirmations"}),"\n",(0,i.jsx)(t.li,{children:"Sending ordered transactions to the data availability layer"}),"\n"]}),"\n",(0,i.jsx)(t.p,{children:"The Mantis rollup will have a rotating set of independent sequencers to ensure that these critical functions are not interrupted and to provide censorship-resistance. This further guarantees intents and solutions are accepted before the end of the scoring period. This will also maintain the credibility of scoring and facilitating blockspace auctions."}),"\n",(0,i.jsxs)(t.p,{children:["The Mantis sequencing design will be similar to ",(0,i.jsx)(t.a,{href:"https://docs.altlayer.io/altlayer-documentation",children:"AltLayer\u2019s restaked rollup design"})," that incorporates a decentralized sequencing network into the rollup\u2019s architecture. Anyone will be able to register as a node on the Mantis rollup. Nodes are then able to become validators if they meet the minimum amount of stake. This provides security for the rollup in a manner that incorporates slashing. This further ensures that transaction inclusion on layer 1 is not done in a malicious way. Node operators will be able to provide their own stake or accept delegations. This reduces the barrier to entry by allowing nodes on Mantis to crowdsource their collateral."]})]})}function h(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},8453:(e,t,n)=>{n.d(t,{R:()=>a,x:()=>r});var i=n(6540);const s={},o=i.createContext(s);function a(e){const t=i.useContext(o);return i.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:a(e.components),i.createElement(o.Provider,{value:t},e.children)}}}]);